// Validate negotiation input. Missing vendor/offer/contact -> NOT_READY downstream, never fabricated here.
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
if (!i.decision || i.decision.decision !== 'NEGOTIATE') throw new Error('Negotiation requires a NEGOTIATE decision');
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, decision: i.decision, vendor: i.vendor ?? null, offer: i.offer ?? null, product: i.product ?? null, procurement: i.procurement ?? {}, allowed_discount_pct: i.allowed_discount_pct ?? null, requested_terms: i.requested_terms ?? [] } }];

// Eligibility + target + facts-only draft (canonical: tools/_lib/negotiation.js). No simulation, no sending.
const inp = $input.first().json;
const reasons = [];
const v = inp.vendor || {}, o = inp.offer || {};
if (!v.vendor_id || !v.vendor_name || v.vendor_name === 'unavailable') reasons.push('no verified vendor identity');
if (!v.source_url) reasons.push('no vendor source URL');
if (!o.offer_id || !o.product_id) reasons.push('no real offer');
if (!(typeof o.net_price === 'number' && o.net_price > 0)) reasons.push('no verified price');
if (!o.currency) reasons.push('no offer currency');
const c = v.contact_channel || {};
if (!c.type || !c.address) reasons.push('no vendor contact information');
else if (c.status === 'UNAVAILABLE') reasons.push('contact channel unavailable');
else if (!c.source_url) reasons.push('contact without verifiable source');
if (o.currency && inp.procurement.currency && String(o.currency).toUpperCase() !== String(inp.procurement.currency).toUpperCase()) reasons.push('currency mismatch (no FX source)');
if (reasons.length) return [{ json: { procurement_id: inp.procurement_id, status: 'NOT_READY', reasons, negotiation: null, message: null, human_confirmation: false, do_not_send: true } }];
let target = null, basis = null;
const sameCcy = String(o.currency).toUpperCase() === String(inp.procurement.currency || o.currency).toUpperCase();
if (typeof inp.procurement.budget === 'number' && inp.procurement.budget > 0 && sameCcy && inp.procurement.budget < o.net_price) { target = inp.procurement.budget; basis = 'procurement_budget'; }
else if (typeof inp.allowed_discount_pct === 'number' && inp.allowed_discount_pct > 0 && inp.allowed_discount_pct < 100) { target = Math.round(o.net_price * (1 - inp.allowed_discount_pct / 100) * 100) / 100; basis = 'explicit_allowed_discount:' + inp.allowed_discount_pct + '%'; }
if (target === null) return [{ json: { procurement_id: inp.procurement_id, status: 'NOT_READY', reasons: ['no negotiation target (target_price unavailable)'], negotiation: null, message: null, human_confirmation: false, do_not_send: true } }];
const discount = Math.round((1 - target / o.net_price) * 10000) / 100;
const negotiation = { procurement_id: inp.procurement_id, product_id: o.product_id, vendor_id: v.vendor_id, offer_id: o.offer_id, current_price: o.net_price, currency: String(o.currency).toUpperCase(), target_price: target, requested_discount_percent: discount, requested_terms: inp.requested_terms, reason: inp.decision.decision_reason, contact_channel: v.contact_channel, status: 'READY_FOR_HUMAN_REVIEW', human_confirmation: false, do_not_send: true, created_at: new Date().toISOString() };
const facts = ['Product: ' + (inp.product?.name ?? o.product_id), 'Current verified price: ' + o.net_price + ' ' + negotiation.currency, 'Requested price: ' + target + ' ' + negotiation.currency];
if (inp.procurement.quantity) facts.push('Quantity: ' + inp.procurement.quantity);
const changes = ['Unit price ' + o.net_price + ' ' + negotiation.currency + ' -> ' + target + ' ' + negotiation.currency].concat(inp.requested_terms.map(String));
const message = { subject: 'Price request: ' + (inp.product?.name ?? o.product_id) + ' (' + o.net_price + ' ' + negotiation.currency + ')', body: ['Dear ' + (v.contact_channel.address ?? 'Sales team') + ',', '', 'We are evaluating ' + (inp.product?.name ?? o.product_id) + ' listed at ' + o.net_price + ' ' + negotiation.currency + (inp.procurement.quantity ? ' (quantity ' + inp.procurement.quantity + ')' : '') + '.', 'We would like to request a revised quotation at ' + target + ' ' + negotiation.currency + '.', ...inp.requested_terms.map((t) => 'We would also like to discuss: ' + t + '.'), '', 'Please reply with your best revised quotation. This request is subject to our standard procurement review; no order is placed by this message.'].join('\n'), facts_used: facts, requested_changes: changes, evidence_urls: inp.product?.evidence_urls ?? [] };
return [{ json: { procurement_id: inp.procurement_id, status: 'READY_FOR_HUMAN_REVIEW', reasons: [], negotiation, message, target_basis: basis, human_confirmation: false, do_not_send: true } }];

// Terminal: sending blocked in Phase 2B regardless of confirmation.
const i = $input.first().json;
return [{ json: { ...i, human_confirmation: i.human_confirmation ?? false, do_not_send: true, send_blocked_reason: 'Phase 2B: external sending requires Phase 2C email infrastructure + explicit human confirmation' } }];

// NOT_READY passthrough: no row, no message, no send. Orchestrator records evaluated_not_ready event.
const i = $input.first().json;
return [{ json: { procurement_id: i.procurement_id, status: 'NOT_READY', reasons: i.reasons ?? [], negotiation: null, message: null, human_confirmation: false, do_not_send: true } }];
